-- ============================================================
-- Combinaciones de especies (relaciones de compatibilidad)
-- Se insertan por nombre, resolviendo IDs con subqueries
-- ============================================================

insert into plant_combinations (plant_a_id, plant_b_id, compatibility_score, aesthetic_score, style_tags)
select
  a.id, b.id, 0.85, 0.80, '{}'
from plants a, plants b
where (a.common_name, b.common_name) in (
